class Shape {
public:
  enum Kind { CIRCLE, SQUARE } kind;
  double r = 0.0;    // circle radius
  double side = 0.0; // square side
};
double area(const Shape& s) {
  switch (s.kind) {
    case Shape::CIRCLE: return 3.14 * s.r * s.r;
    case Shape::SQUARE: return s.side * s.side;
  }
  return 0.0;
}
double perimeter(const Shape& s) {
  switch (s.kind) {
    case Shape::CIRCLE: return 2 * 3.14 * s.r;
    case Shape::SQUARE: return 4 * s.side;
  }
  return 0.0;
}
